package report

import (
	"strings"
	"testing"

	"github.com/aquasecurity/trivy/pkg/types"
	"github.com/future-architect/vuls/models"
)

func TestLibraryReportsUseFindingPath(t *testing.T) {
	result := models.ScanResult{
		ServerName: "test-server",
		ScannedCves: models.VulnInfos{
			"TEST-1": {
				CveID: "TEST-1",
				LibraryFixedIns: models.LibraryFixedIns{
					{Key: "python", Name: "requests", Path: "one/Pipfile.lock", FixedIn: "2.0"},
					{Key: "python", Name: "requests", Path: "two/Pipfile.lock", FixedIn: "2.5"},
				},
			},
		},
		LibraryScanners: models.LibraryScanners{
			{Path: "one/Pipfile.lock", Libs: []types.Library{{Name: "requests", Version: "1.0"}}},
			{Path: "two/Pipfile.lock", Libs: []types.Library{{Name: "requests", Version: "1.5"}}},
		},
	}

	summary := summaryLines(result)
	for _, want := range []string{"requests (one/Pipfile.lock)", "requests (two/Pipfile.lock)"} {
		if !strings.Contains(summary, want) {
			t.Errorf("TUI summary missing %q:\n%s", want, summary)
		}
	}

	fullText := formatFullPlainText(result)
	for _, want := range []string{
		"requests-1.0, FixedIn: 2.0 (one/Pipfile.lock)",
		"requests-1.5, FixedIn: 2.5 (two/Pipfile.lock)",
	} {
		if !strings.Contains(fullText, want) {
			t.Errorf("full text report missing %q:\n%s", want, fullText)
		}
	}
	if got := strings.Count(fullText, "FixedIn:"); got != 2 {
		t.Errorf("full text report has %d library findings, want 2:\n%s", got, fullText)
	}
}

